using System;
using System.IO;
using System.Linq;
using AgentHands;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
public class AgentAcceptance {
 static int count;
 static void Check(bool value,string name){if(!value)throw new Exception("ACCEPTANCE FAILED: "+name);count++;Debug.Log("ACCEPTANCE PASS: "+name);}
 public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);BuildAgentHands.Assets();var rt=new GestureRuntime(Resources.Load<Material>("AgentHandMaterial"));rt.Place(new Vector3(0,1.6f,0),Vector3.forward);rt.Seek(0);Check(rt.Head.activeSelf,"orb before question");var hands=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Where(x=>x.name=="Agent left hand"||x.name=="Agent right hand").ToArray();Check(hands.Length==2&&hands.All(x=>x.gameObject.activeSelf),"two hands before question");rt.SetState("thinking");rt.Seek(1);Check(rt.State=="thinking"&&hands.All(x=>x.gameObject.activeSelf),"thinking retains agent");var o=new RegisteredObject{id="box",position=new[]{0f,1.2f,.7f},size=new[]{.1f,.1f,.1f}};rt.Load(new GesturePlan{tagged="[PointObject; object:box]this",response="this",objects=new[]{o},events=new[]{new GestureEvent{id="point",targetId="box",gesture="point",hand="right",start=1,duration=1,interactivity="none"}}});rt.SetState("idle");rt.Seek(1.5f);Check(rt.State=="gesturing","active gesture state");Check(hands.All(x=>x.gameObject.activeSelf),"unused hand remains visible");var before=hands.Select(x=>x.position).ToArray();rt.Seek(1.999f);var finger=hands.First(x=>x.name=="Agent right hand").Find("Finger 2 phalanx 0");var fingerBefore=finger.localRotation;rt.Seek(2.001f);Check(hands.All(x=>x.gameObject.activeSelf)&&rt.State=="idle","return to persistent idle");Check(hands.Select((x,i)=>Vector3.Distance(x.position,before[i])).All(x=>x<1),"bounded transition");Check(Quaternion.Angle(fingerBefore,finger.localRotation)<5,"finger transition remains bounded");rt.Seek(.5f);Check(rt.LastInteraction=="reset-after-seek","backward seek reset");rt.Load(new GesturePlan{objects=new[]{o},events=new[]{new GestureEvent{id="bad",targetId="missing",duration=1}}});rt.Seek(.1f);Check(rt.Diagnostics.Contains("bad"),"invalid target surfaced without crashing");Check(rt.Plan.tagged==null,"raw model not invented");rt.Load(new GesturePlan{objects=new[]{o},events=new[]{new GestureEvent{id="contact",targetId="box",gesture="point",hand="right",start=0,duration=1,interactivity="highFive"}}});rt.Seek(.2f);Check(rt.State=="interactive","interactive state distinct from speech gesture");var lh=hands.First(x=>x.name=="Agent left hand");var rh=hands.First(x=>x.name=="Agent right hand");rt.Seek(.3f,lh.position,null);Check(!rt.LastInteraction.EndsWith(":contact"),"unused idle hand does not trigger active-hand contact");rt.Seek(.4f,null,rh.position);Check(rt.LastInteraction.EndsWith(":contact"),"active hand contact detected");rt.Seek(3);Check(rt.State=="idle"&&hands.All(x=>x.gameObject.activeSelf),"interaction completion returns to visible idle");rt.IsSpeaking=true;rt.Seek(4);Check(rt.State=="speaking"&&hands.All(x=>x.gameObject.activeSelf),"speech between gestures retains visible embodiment");rt.IsSpeaking=false;bool constructorError=false;Application.LogCallback handler=(message,stack,type)=>{if(message.Contains("persistentDataPath")&&(type==LogType.Exception||type==LogType.Error))constructorError=true;};Application.logMessageReceived+=handler;var lifecycle=new GameObject("Client lifecycle regression");try{lifecycle.AddComponent<LiveClient>();Check(!constructorError,"client construction does not access Unity persistentDataPath");}finally{Application.logMessageReceived-=handler;UnityEngine.Object.DestroyImmediate(lifecycle);}var temp=Path.Combine(Path.GetTempPath(),"agent-key-test-"+Guid.NewGuid());Directory.CreateDirectory(temp);try{var provider=new GeminiDirect(temp);Check(!provider.Load()&&provider.Error.Contains("Missing"),"missing key has actionable error");File.WriteAllText(Path.Combine(temp,"api_key.txt"),"   ");Check(!provider.Load()&&provider.Error.Contains("empty"),"empty key rejected");File.WriteAllText(Path.Combine(temp,"api_key.txt"),"synthetic-not-a-real-key");Check(provider.Load(),"nonempty file loads without embedding");File.WriteAllText(Path.Combine(temp,"models.json"),"{\"responseModel\":\"replacement\",\"ttsModel\":\"gemini-2.5-flash-preview-tts\"}");Check(!provider.Load()&&provider.Error.Contains("approval"),"unapproved replacement blocked");var parsed=DirectPlanParser.Parse("[PointObject; object:box]This is a box.",new[]{o},Vector3.zero,4);Check(parsed.tagged.StartsWith("[PointObject")&&parsed.response=="This is a box."&&parsed.events.Length==1,"raw tags preserved and stripped only for speech");}finally{Directory.Delete(temp,true);}var regionPlan=DirectPlanParser.Parse("[RegionOfObject; object:box, region:F:top:center]top",new[]{o},Vector3.zero,2);var regionObject=Array.Find(regionPlan.objects,x=>x.id==regionPlan.events[0].targetId);Check(Mathf.Abs(regionObject.Position.y-(o.Position.y+o.Size.y/3))<.001f,"native canonical semantic grid resolves to object region");bool invalidRegion=false;try{DirectPlanParser.Parse("[PointObject; object:box, region:whole]box",new[]{o},Vector3.zero,2);}catch(ArgumentException){invalidRegion=true;}Check(invalidRegion,"invented native region rejected before TTS");var wordPlan=DirectPlanParser.Parse("A much [PointObject; object:box]larger box.",new[]{o},Vector3.zero,4);Check(wordPlan.events[0].wordIndex==2&&wordPlan.events[0].start==wordPlan.wordStarts[2],"native debug word and event share weighted timeline");var arbitration=DirectPlanParser.Parse("[PointObject; object:box]This [PointObject; object:box]box [Comparison; handedness:double]size",new[]{o},Vector3.zero,3);Check(arbitration.events[0].hand=="left"&&arbitration.events[1].hand=="right"&&arbitration.events[2].hand=="both"&&arbitration.events[0].start+arbitration.events[0].duration<=arbitration.events[2].start+.001f,"native oldest-hand arbitration and atomic double interruption");var burn=DirectPlanParser.Parse("[Burn]hot",new[]{o},Vector3.zero,2);Check(burn.events[0].effect=="burn","paper warning event reaches runtime VFX");string plain=GeminiDirect.BuildRequestJson("Synthetic harmless request");Check(!plain.Contains("inlineData")&&plain.Contains("maxOutputTokens"),"provider text Part contains exactly text, no empty audio oneof");string audio=GeminiDirect.BuildRequestJson("Describe audio",new byte[]{1,2});Check(audio.Contains("audio/wav")&&audio.Contains("AQI="),"provider audio Part is separate from text Part");var requestOut=Environment.GetEnvironmentVariable("AGENT_HANDS_PROVIDER_REQUEST");if(!string.IsNullOrEmpty(requestOut))File.WriteAllText(requestOut,GeminiDirect.BuildRequestJson("Say clearly: The hands stay visible after the response.",null,true));Debug.Log("AGENT_ACCEPTANCE_PASSED "+count);var path=Environment.GetEnvironmentVariable("AGENT_HANDS_ACCEPTANCE");if(!string.IsNullOrEmpty(path))File.WriteAllText(path,"{\"passed\":"+count+",\"kind\":\"Unity runtime software acceptance, not physical device\"}");}
}
